import os, re, json

d = '/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/seen-reference-3/play/users/u051/system/state'
sessions_path = os.path.join(d, 'sessions', '01a1a16d-0c70-72f0-80fc-983d27b95251.jsonl')

with open(sessions_path) as f:
    content = f.read()

# Find all JSON blocks
json_blocks = re.findall(r'\{[^{}]*\}', content)

# Parse each JSON message
