import os, json

d = '/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/seen-reference-3/play/users/u051/system/state'
sessions_path = os.path.join(d, 'sessions', '01a1a16d-0c70-72f0-80fc-983d27b95251.jsonl')

with open(sessions_path) as f:
    lines = f.readlines()

# Look for recent messages that might have demo pairs (after my request_demos)
request_line = None
for i, line in enumerate(lines):
    try:
        msg = json.loads(line)
        if 'message' in msg:
            typ = msg.get('type', '').split(':')[0]
            if typ == 'message':
                content = msg['message'].get('content', [])
                if content and isinstance(content[0], dict) and content[0].get('type') == 'text':
                    text = content[0].get('text', '')
                    if 'request_demos' in text:
                        request_line = i
                        break
    except:
        pass

print(f"request_demos found at line: {request_line}")

# Now search for content after that line
demo_found = -1
for i in range(request_line, min(request_line + 20, len(lines))):
    line = lines[i]
    try:
        msg = json.loads(line)
        typ = msg.get('type', '').split(':')[0]
        if typ == 'message':
            content = msg['message'].get('content', [])
            for c in content:
                if isinstance(c, dict):
                    if c.get('type') == 'text':
                        text = c.get('text', '')
                        if 'Demo pair' in text:
                            demo_found = i
                            print(f"Demo pair found at line: {demo_found}")
                            break
                        if 'Task id' in text and 'Demo requests used' in text:
                            print(f"Next task message at line: {i}")
                            print(text[:500])
    except:
        pass

# Print actual demo content if found
if demo_found > 0:
    print(f"\n=== Demo content from line {demo_found} ===")
    print(lines[demo_found])

